import {mountResearchHome} from './research-home.js';
import {knowledgeGraph} from './knowledge-graph.js';
import {mountStory} from './story-player.js';
import {mountPathIndex,enhanceScenarioReader} from './reader-experience.js';
import {mountField} from './universe-field.js';
let cleanupResearchHome=()=>{},cleanupMindPage=()=>{},graphPage=0,mindPaused=matchMedia('(prefers-reduced-motion: reduce)').matches;
import {services,domains,connections,insights,serviceById,domainById,domainFor} from './catalog.js';
import {s3Notes} from './s3-notes.js';
import {profileFor} from './security-data.js';
import {commandFor} from './defensive-commands.js';
import {communityDetections,detectionsForService,detectionCoverage,detectionSearchText,detectionLibraryUrl,detectionReviewDate} from './community-detections.js';
import {scenarios,scenarioById,scenariosForService,scenarioSources,researchForDomain,researchSources} from './scenario-data.js';

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={key:'M14 4a6 6 0 1 1-4 10l-6 6H1v-3l6-6a6 6 0 0 1 7-7Zm3 3h.01',chip:'M6 6h12v12H6zM9 9h6v6H9zM9 2v4m6-4v4M9 18v4m6-4v4M2 9h4m-4 6h4m12-6h4m-4 6h4',database:'M20 5c0 2-4 3-8 3S4 7 4 5s4-3 8-3 8 1 8 3ZM4 5v14c0 2 4 3 8 3s8-1 8-3V5M4 12c0 2 4 3 8 3s8-1 8-3',network:'M9 3h6v6H9zM2 16h6v6H2zM16 16h6v6h-6zM12 9v4M5 16v-3h14v3',shield:'M12 2 3 6v7c0 5 9 9 9 9s9-4 9-9V6L12 2Zm-5 10 3 3 7-7',layers:'m12 2 10 6-10 6L2 8l10-6ZM2 12l10 6 10-6M2 16l10 6 10-6',workflow:'M3 3h6v6H3zM15 15h6v6h-6zM6 9v9h9M9 6h9v9',chart:'M3 3v18h19M7 16v-5m5 5V6m5 10v-8',doc:'M5 2h10l4 4v16H5V2Zm10 0v5h4M8 11h8M8 15h8M8 18h5'};
function icon(name,attrs=''){return `<svg ${attrs} viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.doc}"/></svg>`;}
const linkOut=(url,label,cls='')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} <span>↗</span></a>`;
let docs={documents:[],references:[],stats:{fetched:0,sections:0,references:0}},loadError=false,activeTab='intel',graphMode='security',routeState={},universeDetail=false,transitioning=false;
const visits=[];
let saved=[];
try{saved=JSON.parse(localStorage.getItem('trace-saved')||'[]');if(!Array.isArray(saved))saved=[];}catch{saved=[];}
try{const res=await fetch('./generated/docs.json');if(!res.ok)throw Error(res.status);docs=await res.json();}catch{loadError=true;}
const docFor=id=>docs.documents.find(d=>d.id===id&&d.status==='ok');
const refsFor=id=>docs.references.filter(r=>r.from===id&&serviceById(r.from)&&serviceById(r.to));
const connected=id=>connections.filter(c=>c.from===id||c.to===id);
const other=(c,id)=>c.from===id?c.to:c.from;
const date=iso=>iso?new Date(iso).toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):'Not fetched';

$('#domain-nav').innerHTML=domains.map(d=>`<a class="domain-link" href="#/domain/${d.id}" style="--color:${d.color}" data-domain="${d.id}">${icon(d.icon)}<span>${esc(d.short)}</span><span class="count">${String(d.services.length).padStart(2,'0')}</span></a>`).join('');
function breadcrumb(items=[]){return `<div class="breadcrumb"><a href="#/">Atlas</a><span class="separator">/</span><a href="#/">AWS universe</a>${items.map(([label,url],i)=>`<span class="separator">/</span>${url?`<a href="${url}">${esc(label)}</a>`:`<span class="current">${esc(label)}</span>`}`).join('')}</div>`;}
function announce(text){$('#announcement').textContent=text;}
function provenance(doc){return `<div class="provenance"><span class="source-dot"></span> ${doc?`Source fetched ${date(doc.fetchedAt)}.`:loadError?'Documentation index unavailable.':'Independent documentation atlas.'}<br>${doc?linkOut(doc.resolvedUrl,'Read the original AWS page'): '<a href="#/sources">Explore sources & methodology ↗</a>'}</div>`;}
function mapPage(type,id,topicIndex){
  if(matchMedia('(prefers-reduced-motion: reduce)').matches)mindPaused=true;
  const d=type==='domain'?domainById(id):domainFor(id),s=type==='service'?serviceById(id):null;
  if((type==='domain'&&!d)||(type==='service'&&!s))return notFound();
  const topic=s&&Number.isInteger(topicIndex)?docFor(id)?.sections[topicIndex]:null;
  routeState={type,id,d,s,topic,topicIndex};
  const title=s?(topic?esc(topic.title):esc(s.name)):d?esc(d.name):'Enter the <em>AWS</em><br>security universe.';
  const subtitle=s?(topic?'Investigate how this AWS capability changes attack paths, observable evidence, and response controls.':profileFor(s.id).boundary):d?d.description:'Follow identities, workloads, data, and evidence across real cloud attack and response paths.';
  const crumbs=d?[[d.short,s?`#/domain/${d.id}`:null],...(s?[[s.name,topic?`#/service/${id}`:null]]:[]),...(topic?[[topic.title,null]]:[])]:[];
  const depth=topic?4:s?3:d?2:1;
  $('#view').innerHTML=`<section class="map-page mind-page" style="--color:${d.color}">
    <header class="map-header mind-header">${breadcrumb(crumbs)}<div class="heading-row"><div><p class="mind-eyebrow">${topic?'SOURCE KNOWLEDGE':s?'SERVICE INTELLIGENCE':'SECURITY DOMAIN'} / LAYER 0${depth}</p><h1 class="map-title">${title}</h1><p class="map-subtitle">${esc(subtitle)}</p></div><div class="mind-header-aside"><span>${topic?'READ THE SOURCE':s?'THINK ACROSS BOUNDARIES':'CHOOSE YOUR POINT OF ENTRY'}</span><p>${s?'Threat context. Evidence.<br>Defense. Connected.':d.services.length+' services.<br>One connected investigation.'}</p><a href="#/paths">Follow a research path ↗</a></div></div></header>
    <div class="mind-workspace"><div class="mind-toolbar"><div><span class="mind-eyebrow">${topic?'KNOWLEDGE MAP':s?'CONNECTED SECURITY CONTEXT':'INSIDE THE DOMAIN'}</span><p>${s?'Select a node to follow its context and sources.':'Select a service to explore threats, evidence, and controls.'}</p></div><button id="mind-reading" aria-pressed="false">Reading view</button><button id="mind-motion" aria-pressed="${mindPaused}">${mindPaused?'Resume motion':'Pause motion'}</button></div>
    <div class="mind-grid"><div class="explore-column"><div class="canvas-wrap"><canvas class="atlas-field" aria-hidden="true"></canvas><svg class="world-svg" role="group" aria-label="Interactive AWS knowledge graph. Tab to nodes, Enter to explore, drag background to pan." viewBox="0 0 1200 800" tabindex="0"></svg></div><div class="map-bottom"><div class="map-key"><span id="legend-text"></span></div><div class="map-controls"><button id="zoom-out" aria-label="Zoom out">−</button><span class="zoom-label" id="zoom-label">100%</span><button id="zoom-in" aria-label="Zoom in">+</button><button id="zoom-fit" aria-label="Fit graph to view">⊡</button></div></div><div class="mind-graph-pagination"></div><section class="mind-ledger"><div class="mind-section-title"><span>WHY THESE NODES CONNECT</span><small>Sources travel with the relationship.</small></div><div class="mind-ledger-items"></div></section></div><aside class="inspector" aria-label="Selected node details" style="--color:${d.color}"></aside></div></div>
    <div class="depth-bar"><a href="#/"><b>01</b> Universe</a><i class="depth-line"></i><a href="#/domain/${d.id}" class="${depth===2?'current':''}"><b>02</b> Domain</a><i class="depth-line"></i><a href="#/service/${s?.id||d.services[0]}" class="${depth>=3?'current':''}"><b>03</b> Service</a><a class="mind-depth-source" href="#/sources">Research index ↗</a></div>
  </section>`;
  renderPanel();renderGraph();decoratePage();
  const field=mountField($('.canvas-wrap'),mindPaused),button=$('#mind-motion'),motion=matchMedia('(prefers-reduced-motion: reduce)');
  const setMotion=value=>{mindPaused=value;field.setPaused(value);button.setAttribute('aria-pressed',String(value));button.textContent=value?'Resume motion':'Pause motion';if(value)$('.world-svg')?.pauseAnimations();else $('.world-svg')?.unpauseAnimations();};
  button.onclick=()=>setMotion(!mindPaused);
  $('#mind-reading').onclick=()=>{const reading=$('.mind-page').classList.toggle('mind-reading-mode');$('#mind-reading').setAttribute('aria-pressed',String(reading));$('#mind-reading').textContent=reading?'Show map':'Reading view';
    if(reading){$('.mind-page').classList.remove('is-focus');$('#focus-graph').setAttribute('aria-pressed','false');$('#focus-graph').textContent='Focus graph';}
  };
  const motionChanged=()=>setMotion(motion.matches);motion.addEventListener('change',motionChanged);
  cleanupMindPage=()=>{field.destroy();motion.removeEventListener('change',motionChanged);};
  $('.mind-toolbar').append($('.reading-controls'));
  if($('.trail-history'))$('.mind-header').append($('.trail-history'));
  $('#focus-graph').addEventListener('click',()=>{$('.mind-page').classList.remove('mind-reading-mode');$('#mind-reading').setAttribute('aria-pressed','false');$('#mind-reading').textContent='Reading view';});
  document.title=`${topic?.title||s?.name||d?.name||'Explore the AWS universe'} — TRACE`;
}
function renderFieldCommand(panel,item){
  const label=document.createElement('div');
  label.className='panel-label source-heading';
  label.textContent='READ-ONLY FIELD CHECK / AWS CLI';
  const list=document.createElement('ol');
  list.className='defense-list';
  const row=document.createElement('li');
  row.className='field-command';
  const badge=document.createElement('span');
  badge.textContent='CLI';
  const content=document.createElement('p');
  const title=document.createElement('strong');
  title.textContent=item.title;
  const command=document.createElement('code');
  command.textContent=item.command;
  const source=document.createElement('a');
  source.href=item.source;
  source.target='_blank';
  source.rel='noopener noreferrer';
  source.textContent='AWS CLI reference ↗';
  content.append(title,document.createElement('br'),command,document.createElement('br'),source);
  row.append(badge,content);
  list.append(row);
  const note=document.createElement('p');
  note.className='map-tools-note';
  note.textContent='Confirm the active account and Region where applicable. Replace values in angle brackets. These checks read configuration or status; they do not prove that a control is effective.';
  panel.querySelector('.source-button').before(label,list,note);
}

const ruleBasisLabel=rule=>rule.basis==='Exact upstream selection'?'EXACT UPSTREAM SELECTION':rule.basis.toUpperCase();
function ruleLinks(rule,compact=false){return `<div class="detection-links">${linkOut(rule.source,compact?'Community page':'View on detections.ai','source-button')}${rule.upstream?linkOut(rule.upstream,compact?'Upstream rule':'Open pinned upstream rule','source-button'):''}</div>`;}
function detectionSummaryCards(rules,mode){
  if(!rules.length)return '<p class="empty-note detection-gap-inline">No reviewed community detection is mapped to this node. TRACE leaves this visible instead of generating a rule.</p>';
  if(mode==='intel')return `<div class="detection-intel-list">${rules.slice(0,3).map(rule=>`<a href="${esc(rule.source)}" target="_blank" rel="noopener noreferrer"><span>${esc(rule.language)} · ${esc(rule.contributor)}</span><strong>${esc(rule.title)}</strong><p>${esc(rule.summary)}</p>${rule.mitre.length?`<small>${rule.mitre.map(id=>`MITRE ${esc(id)}`).join(' · ')}</small>`:''}</a>`).join('')}</div>`;
  if(mode==='evidence')return `<div class="detection-evidence-list">${rules.slice(0,3).map(rule=>`<article><span>${esc(rule.title)}</span><ul>${rule.signals.map(signal=>`<li>${esc(signal)}</li>`).join('')}</ul><p><b>Requires</b> ${esc(rule.telemetry)}</p><a href="${esc(rule.source)}" target="_blank" rel="noopener noreferrer">Review native ${esc(rule.language)} rule ↗</a></article>`).join('')}</div>`;
  return `<div class="detection-tuning-list">${rules.slice(0,3).map(rule=>`<article><span>${esc(rule.title)}</span><p>${esc(rule.tune)}</p>${rule.applicability?`<small>${esc(rule.applicability)}</small>`:''}<a href="${esc(rule.source)}" target="_blank" rel="noopener noreferrer">Source and rule context ↗</a></article>`).join('')}</div>`;
}
function renderCommunityDetections(body,rules,profile){
  if(!rules.length){
    body.innerHTML=`<div class="detection-intro detection-gap"><span>COMMUNITY DETECTIONS / REVIEWED COVERAGE GAP</span><h3>No defensible rule is mapped here.</h3><p>This is a visible research gap, not evidence that the service is quiet. TRACE does not generate substitute SQL or translate an unreviewed rule into a made-up common dialect.</p></div><div class="detection-gap-actions">${linkOut(detectionLibraryUrl,'Search the community library','source-button')}${linkOut(profile.source,'Review service telemetry','source-button')}</div>`;
    return;
  }
  body.innerHTML=`<div class="detection-intro"><span>COMMUNITY DETECTIONS / ${rules.length} REVIEWED</span><h3>Native rules, with provenance intact.</h3><p>Exact predicates appear only when the upstream selection was reviewed. Other cards show the publisher's public signal summary and link to the native rule instead of inventing a translation.</p></div><div class="detection-stack">${rules.map(rule=>`<article class="detection-card"><div class="detection-card-head"><span>${esc(rule.language)}</span><span>${esc(ruleBasisLabel(rule))}</span></div><h3>${esc(rule.title)}</h3><p class="detection-summary">${esc(rule.summary)}</p><dl class="detection-meta"><div><dt>CONTRIBUTOR</dt><dd>${esc(rule.contributor)}</dd></div><div><dt>COLLECTION</dt><dd>${esc(rule.collection)}</dd></div><div><dt>STATUS</dt><dd>${esc(rule.status)} · ${esc(rule.level)}</dd></div></dl><div class="panel-label">${esc(ruleBasisLabel(rule))}</div><ul class="detection-signals">${rule.signals.map(signal=>`<li>${esc(signal)}</li>`).join('')}</ul><div class="detection-requirement"><span>TELEMETRY REQUIRED</span><p>${esc(rule.telemetry)}</p></div><div class="detection-tune"><span>TRIAGE / TUNING</span><p>${esc(rule.tune)}</p>${rule.applicability?`<small>${esc(rule.applicability)}</small>`:''}</div>${rule.mitre.length?`<div class="detection-mitre">${rule.mitre.map(id=>`<span>MITRE ${esc(id)}</span>`).join('')}</div>`:''}${ruleLinks(rule)}</article>`).join('')}</div><p class="detection-review-note">Curated from the public community index and upstream projects · reviewed ${esc(detectionReviewDate)} · validate field mappings and thresholds against your own pipeline.</p>`;
}

function renderPanel(){const {type,d,s,topic,topicIndex}=routeState;const panel=$('.inspector');
  if(type==='universe'){
    panel.innerHTML=`<span class="entry-label">YOUR FIRST INCIDENT</span><h2>One web request.<br>A whole AWS identity.</h2><p class="inspector-intro">Trace an SSRF path from the edge to instance metadata, temporary credentials, data access, and response evidence.</p><a href="#/scenario/web-to-role" class="start-path">Trace the attack path <span>↗</span></a><div class="entry-stats"><div><strong>${services.length}</strong><small>services</small></div><div><strong>${docs.stats.sections}</strong><small>source topics</small></div><div><strong>08</strong><small>security domains</small></div></div>${provenance()}`;
  }else if(type==='domain'){
    panel.innerHTML=`<div class="inspector-kicker"><span>DOMAIN / 02</span><span class="number">${String(d.services.length).padStart(2,'0')} SERVICES</span></div><div class="detail-icon">${icon(d.icon)}</div><h2>${esc(d.name)}</h2><p class="inspector-intro">${esc(d.description)}</p><div class="service-list">${d.services.map(id=>{const v=serviceById(id);return `<a href="#/service/${id}">${icon(d.icon)}<span><strong>${esc(v.name)}</strong><small>${esc(v.label)}</small></span><span class="arrow">↗</span></a>`;}).join('')}</div><p class="map-tools-note">Domains are TRACE’s navigation categories. Dashed graph lines group services in this editorial domain. Open a service to inspect documented capabilities and scenario relationships.</p>${provenance()}`;
  }else if(topic){
    const doc=docFor(s.id),profile=profileFor(s.id),related=scenariosForService(s.id),rules=detectionsForService(s.id),children=[];
    const note=s.id==='s3'?s3Notes[topic.title]:null;
    for(let i=topicIndex+1;i<doc.sections.length&&doc.sections[i].level>topic.level;i++)children.push({...doc.sections[i],index:i});
    const neighbors=(children.length?children:doc.sections.filter((_,i)=>i!==topicIndex).slice(0,6).map(t=>({...t,index:doc.sections.indexOf(t)})));
    panel.innerHTML=`<div class="inspector-kicker"><span>SECURITY ANALYSIS / 04</span><span class="number">AWS SOURCE ${String(topicIndex+1).padStart(2,'0')}</span></div><div class="detail-icon">${icon('doc')}</div><p class="service-type">${esc(s.name)} · ${esc(d.short)}</p><h2>${esc(topic.title)}</h2><div class="topic-analysis-note"><span>ANALYST SECURITY LENS</span><p>Use this topic to test service-specific attack hypotheses, telemetry, and controls. The linked AWS section remains the authority for exact service behavior.</p></div>${note?`<div class="topic-editorial"><span>SOURCE-BASED EDITORIAL NOTE</span><p>${esc(note)}</p></div>`:''}<div class="topic-security-lens"><section class="topic-block topic-boundary"><div class="panel-label">SECURITY BOUNDARY</div><p>${esc(profile.boundary)}</p></section><section class="topic-block topic-threat-block"><div class="panel-label">ATTACK HYPOTHESES / VALIDATE IN AN AUTHORIZED ENVIRONMENT</div><ol class="intel-list">${profile.threats.map((v,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><p>${esc(v)}</p></li>`).join('')}</ol></section><section class="topic-block topic-evidence-block"><div class="panel-label">OBSERVABLE EVIDENCE</div><ul class="evidence-list">${profile.evidence.map(v=>`<li><i></i><span>${esc(v)}</span></li>`).join('')}</ul></section><section class="topic-block topic-defense-block"><div class="panel-label">CONTROLS TO TEST</div><ol class="defense-list">${profile.defenses.map((v,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><p>${esc(v)}</p></li>`).join('')}</ol></section><div class="responder-question"><span>RESPONDER QUESTION</span><p>${esc(profile.responder)}</p></div>${rules.length?`<section class="topic-block"><div class="panel-label">SERVICE-LEVEL COMMUNITY RULE</div>${detectionSummaryCards(rules.slice(0,1),'intel')}</section>`:''}${related.length?`<section class="topic-block"><div class="panel-label">RELATED INCIDENT PATHS</div><div class="scenario-mini-list">${related.slice(0,3).map(v=>`<a href="#/scenario/${v.id}"><span>${esc(v.kicker.split(' -> ')[0])}</span><strong>${esc(v.title)}</strong><small>${v.services.length} connected services</small></a>`).join('')}</div></section>`:''}</div><div class="topic-source-actions">${linkOut(topic.url,'Open exact AWS section','source-button')}${profile.source!==topic.url?linkOut(profile.source,'AWS security guidance','source-button'):''}</div><dl class="topic-meta"><div><dt>GUIDE</dt><dd>${esc(doc.title)}</dd></div><div><dt>POSITION</dt><dd>Section ${topicIndex+1} · heading level ${topic.level}</dd></div><div><dt>IMPORTED</dt><dd>${date(doc.fetchedAt)}</dd></div></dl><div class="panel-section topic-neighbors"><h3>${children.length?'TOPICS IN THIS SECTION':'CONTINUE EXPLORING'}</h3>${neighbors.map(t=>`<a class="topic-link" href="#/service/${s.id}/topic/${t.index}">${esc(t.title)} <span>↗</span></a>`).join('')}</div><a class="text-link" href="#/service/${s.id}">← All ${esc(s.short)} topics</a>${provenance(doc)}`;
  }else{
    const doc=docFor(s.id),profile=profileFor(s.id),related=scenariosForService(s.id),research=researchForDomain(d.id),rules=detectionsForService(s.id);
    const tabs=[['intel','Intel'],['evidence','Evidence'],['detections','Detections'],['defense','Defense'],['docs','AWS docs']];
    panel.innerHTML=`<div class="inspector-kicker"><span>SECURITY NODE / 03</span><span class="number">${esc(d.short.toUpperCase())}</span></div><div class="detail-icon">${icon(d.icon)}</div><p class="service-type">${esc(s.label)}</p><h2>${esc(s.name)}</h2><div class="tabs" role="tablist" aria-label="Service security information">${tabs.map(([tab,label])=>`<button role="tab" id="tab-${tab}" aria-selected="${activeTab===tab}" aria-controls="tab-panel" class="${activeTab===tab?'active':''}" data-tab="${tab}">${label}</button>`).join('')}</div><div id="tab-panel" role="tabpanel" aria-labelledby="tab-${activeTab}"></div>${provenance(doc)}`;
    panel.querySelectorAll('[data-tab]').forEach(btn=>btn.onclick=()=>{graphPage=0;activeTab=btn.dataset.tab;graphMode=activeTab==='docs'?'docs':'security';renderPanel();renderGraph();$(`#tab-${activeTab}`)?.focus();});
    const body=$('#tab-panel');
    if(activeTab==='intel'){
      body.innerHTML=`<div class="security-boundary"><span>SECURITY BOUNDARY</span><p>${esc(profile.boundary)}</p></div><div class="panel-label">COMMON ABUSE PATHS / DEFENSIVE MODEL</div><ol class="intel-list">${profile.threats.map((v,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><p>${esc(v)}</p></li>`).join('')}</ol><div class="panel-label source-heading">COMMUNITY-OBSERVED RULES / ${rules.length}</div>${detectionSummaryCards(rules,'intel')}<div class="panel-label source-heading">CROSS-SERVICE SCENARIOS</div><div class="scenario-mini-list">${related.map(v=>`<a href="#/scenario/${v.id}"><span>${esc(v.kicker.split(' -> ')[0])}</span><strong>${esc(v.title)}</strong><small>${v.services.length} connected services</small></a>`).join('')||'<p class="empty-note">This node has no published cross-service scenario yet.</p>'}</div>`;
    }else if(activeTab==='evidence'){
      body.innerHTML=`<div class="panel-label">OBSERVABLE EVIDENCE</div><ul class="evidence-list">${profile.evidence.map(v=>`<li><i></i><span>${esc(v)}</span></li>`).join('')}</ul><div class="panel-label source-heading">RULE SIGNALS & TELEMETRY</div>${detectionSummaryCards(rules,'evidence')}<div class="responder-question"><span>RESPONDER QUESTION</span><p>${esc(profile.responder)}</p></div>${related.slice(0,2).map(v=>`<a class="scenario-signal" href="#/scenario/${v.id}"><span>TRACE IN SCENARIO</span><strong>${esc(v.title)}</strong><small>${esc(v.stages.find(x=>x.service===s.id)?.signal||v.summary)}</small></a>`).join('')}`;
    }else if(activeTab==='detections'){
      renderCommunityDetections(body,rules,profile);
    }else if(activeTab==='defense'){
      body.innerHTML=`<div class="panel-label">PREVENT / CONTAIN / RECOVER</div><ol class="defense-list">${profile.defenses.map((v,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><p>${esc(v)}</p></li>`).join('')}</ol>${linkOut(profile.source,'Official AWS security guidance','source-button')}<div class="panel-label source-heading">RULE TUNING & FALSE POSITIVES</div>${detectionSummaryCards(rules,'defense')}<div class="panel-label source-heading">TRADECRAFT & VALIDATION SOURCES</div><div class="research-links">${research.map(v=>`<a href="${esc(v.url)}" target="_blank" rel="noopener noreferrer"><span>${esc(v.kind)}</span><strong>${esc(v.publisher)}</strong><small>${esc(v.label)}</small></a>`).join('')}</div><p class="map-tools-note">Community sources describe authorized assessment and emulation techniques. AWS documentation remains authoritative for service behavior and controls.</p>`;
    }else{
      body.innerHTML=`<input class="topic-filter" aria-label="Filter documentation topics" placeholder="Filter AWS topics..."><div id="topic-list"></div>`;
      const fill=q=>{$('#topic-list').innerHTML=(doc?.sections||[]).map((t,i)=>({...t,i})).filter(t=>t.title.toLowerCase().includes(q)).map(t=>`<a class="topic-link" href="#/service/${s.id}/topic/${t.i}">${esc(t.title)}<small>Official guide / section ${t.i+1}</small></a>`).join('')||'<p class="empty-note">No matching headings in the imported page. Open the AWS guide for the complete documentation.</p>';};fill('');$('.topic-filter').oninput=e=>fill(e.target.value.toLowerCase());
    }
  }
  if(activeTab==='defense') renderFieldCommand(panel,commandFor(s.id));
}

let camera={x:0,y:0,w:1200,h:800},baseCamera={x:0,y:0,w:1200,h:800};
function renderGraph(){
  const svg=$('.world-svg');if(!svg||$('.research-home'))return;
  const {type,d,s,topic,topicIndex}=routeState;
  const result=knowledgeGraph({type,d,s,topic,topicIndex,doc:s?docFor(s.id):null,tab:activeTab,page:graphPage,references:s?refsFor(s.id):[]});
  graphPage=result.current;svg.innerHTML=result.markup;
  $('#legend-text').textContent=result.legend;
  $('.mind-ledger-items').innerHTML=result.ledger||'<p class="empty-note">Use the service research panel to explore this node.</p>';
  $('.mind-graph-pagination').innerHTML=`<span>${result.total} connections · Page ${result.current+1} of ${result.pages}</span><div><button id="graph-previous" ${result.current===0?'disabled':''}>← Previous nodes</button><button id="graph-next" ${result.current===result.pages-1?'disabled':''}>More nodes →</button></div>`;
  $('#graph-previous').onclick=()=>{graphPage--;renderGraph();};
  $('#graph-next').onclick=()=>{graphPage++;renderGraph();};
  const graphNodes=[...svg.querySelectorAll('.mind-graph-node')],rowHeights=[240,240,240];
  graphNodes.forEach((n,i)=>{const h=Math.max(240,n.querySelector('.mind-node-copy').scrollHeight+135);rowHeights[i%3]=Math.max(rowHeights[i%3],h);});
  const rowY=[45,45+rowHeights[0]+35,45+rowHeights[0]+rowHeights[1]+70],graphHeight=Math.max(850,rowY[2]+rowHeights[2]+45),hubY=graphHeight/2;
  svg.querySelector('.mind-hub').setAttribute('transform',`translate(600 ${hubY})`);
  graphNodes.forEach((n,i)=>{const x=i<3?70:870,y=rowY[i%3],height=rowHeights[i%3];n.setAttribute('transform',`translate(${x},${y})`);n.querySelector('.mind-node-back').setAttribute('height',height);n.querySelector('foreignObject').setAttribute('height',height-130);
    const nx=x+130,ny=y+48,dx=nx-600,dy=ny-hubY,length=Math.hypot(dx,dy),ux=dx/length,uy=dy/length;
    let a={x:600+ux*57,y:hubY+uy*57},b={x:nx-ux*36,y:ny-uy*36};
    if(n.dataset.incoming==='true')[a,b]=[b,a];
    const link=svg.querySelector('#mind-edge-'+i);link.setAttribute('d',`M${a.x},${a.y} C${(a.x+b.x)/2},${a.y} ${(a.x+b.x)/2},${b.y} ${b.x},${b.y}`);
    if(n.dataset.kind!=='membership')link.setAttribute('marker-end','url(#mind-direction)');
  });
  svg.querySelector('rect[fill="url(#mind-grid)"]').setAttribute('height',graphHeight);
  baseCamera={x:0,y:0,w:1200,h:graphHeight};camera={...baseCamera};setCamera();bindMap(svg);
  if(mindPaused)svg.pauseAnimations();
  if(document.fonts.status==='loading')document.fonts.ready.then(()=>{if(svg.isConnected&&svg===$('.world-svg'))renderGraph();});
}
function setCamera(){const svg=$('.world-svg');if(!svg)return;svg.setAttribute('viewBox',`${camera.x} ${camera.y} ${camera.w} ${camera.h}`);$('#zoom-label').textContent=Math.round(baseCamera.w/camera.w*100)+'%';}
function zoom(factor,center){const old={...camera};const width=Math.max(360,Math.min(2600,old.w*factor));factor=width/old.w;const p=center||{x:old.x+old.w/2,y:old.y+old.h/2};camera={x:p.x-(p.x-old.x)*factor,y:p.y-(p.y-old.y)*factor,w:width,h:old.h*factor};setCamera();}
function navigateNode(n){
  $('#graph-tooltip').classList.remove('visible');
  if(transitioning)return;
  if(matchMedia('(prefers-reduced-motion: reduce)').matches||n.dataset.route===location.hash){location.hash=n.dataset.route;return;}
  const svg=$('.world-svg'),start={...camera},m=n.transform.baseVal.consolidate()?.matrix;
  if(!m){location.hash=n.dataset.route;return;}
  transitioning=true;const target={x:m.e-start.w*.28,y:m.f-start.h*.28,w:start.w*.56,h:start.h*.56};let first;
  const frame=t=>{if($('.world-svg')!==svg){transitioning=false;return;}first??=t;const p=Math.min(1,(t-first)/230),ease=1-(1-p)**3;for(const key of ['x','y','w','h'])camera[key]=start[key]+(target[key]-start[key])*ease;setCamera();if(p<1)requestAnimationFrame(frame);else{transitioning=false;location.hash=n.dataset.route;}};
  requestAnimationFrame(frame);
}
function bindMap(svg){let drag=null,moved=false;const point=e=>new DOMPoint(e.clientX,e.clientY).matrixTransform(svg.getScreenCTM().inverse());
  function highlight(n){if(routeState.type!=='universe')return;const [,kind,id]=n.dataset.route.split('/');const ids=new Set([id]);if(kind==='domain')domainById(id)?.services.forEach(x=>ids.add(x));else{docs.references.filter(r=>r.from===id||r.to===id).forEach(r=>{ids.add(r.from);ids.add(r.to);});scenariosForService(id).forEach(scenario=>scenario.services.forEach(service=>ids.add(service)));}svg.classList.add('has-focus');svg.querySelectorAll('[data-route]').forEach(el=>el.classList.toggle('is-neighbor',ids.has(el.dataset.route.split('/')[2])));svg.querySelectorAll('.map-link').forEach(el=>el.classList.toggle('is-neighbor',ids.has(el.dataset.from)&&ids.has(el.dataset.to)));}
  function tip(n,event){const [,kind,id,sub,index]=n.dataset.route.split('/'),d=kind==='domain'?domainById(id):domainFor(id),s=serviceById(id);const title=kind==='domain'?d.name:sub==='topic'?docFor(id)?.sections[Number(index)]?.title:s?.name;const description=kind==='domain'?d.description:sub==='topic'?'Follow the AWS topic and its service security context.':s?.label;const tip=$('#graph-tooltip');tip.innerHTML=`<strong>${esc(title||'Documentation')}</strong><p>${esc(description||'Explore this source-linked node.')}</p><small>${kind==='domain'?'ENTER DOMAIN':'EXPLORE NODE'} ↗</small>`;const box=n.getBoundingClientRect();tip.style.left=Math.max(12,Math.min(innerWidth-268,(event?.clientX||box.right)+18))+'px';tip.style.top=Math.max(12,Math.min(innerHeight-140,(event?.clientY||box.top)+18))+'px';tip.classList.add('visible');}
  svg.querySelectorAll('[data-route]').forEach(n=>{n.addEventListener('pointerenter',e=>{highlight(n);tip(n,e);});n.addEventListener('focus',()=>{highlight(n);tip(n);});n.addEventListener('pointerleave',()=>{svg.classList.remove('has-focus');$('#graph-tooltip').classList.remove('visible');});n.addEventListener('blur',()=>{svg.classList.remove('has-focus');$('#graph-tooltip').classList.remove('visible');});});
  svg.querySelectorAll('[data-route]').forEach(n=>{n.onclick=e=>{if(moved)return;e.stopPropagation();navigateNode(n);};n.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();navigateNode(n);}};});
  svg.onpointerdown=e=>{if(e.button!==0)return;const p=point(e);drag={p,x:camera.x,y:camera.y,screenX:e.clientX,screenY:e.clientY};moved=false;if(!e.target.closest('[data-route]'))svg.setPointerCapture(e.pointerId);};
  svg.onpointermove=e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.screenX,e.clientY-drag.screenY)>5)moved=true;if(!moved)return;const p=point(e);camera.x+=drag.p.x-p.x;camera.y+=drag.p.y-p.y;setCamera();};
  const end=()=>{drag=null;setTimeout(()=>{moved=false;},0);};svg.onpointerup=end;svg.onpointercancel=end;svg.onlostpointercapture=end;
  svg.onwheel=e=>{if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();zoom(Math.exp(Math.max(-100,Math.min(100,e.deltaY))*.0015),point(e));};
  svg.onkeydown=e=>{if(e.target!==svg)return;const moves={ArrowLeft:[-60,0],ArrowRight:[60,0],ArrowUp:[0,-60],ArrowDown:[0,60]};if(moves[e.key]){e.preventDefault();camera.x+=moves[e.key][0];camera.y+=moves[e.key][1];setCamera();}if(e.key==='+'||e.key==='=')zoom(.8);if(e.key==='-')zoom(1.25);};
  $('#zoom-in').onclick=()=>zoom(.8);$('#zoom-out').onclick=()=>zoom(1.25);$('#zoom-fit').onclick=()=>{camera={...baseCamera};setCamera();};
}

function decoratePage(){const page=$('.map-page');if(!page)return;const {type,d,s,topic}=routeState;
  page.classList.toggle('universe-view',type==='universe');
  if(type==='universe'){
    $('.heading-row').insertAdjacentHTML('afterbegin','<div class="map-overline">MAP THE ATTACK SURFACE</div>');
    page.insertAdjacentHTML('beforeend',`<div class="scene-switch" role="group" aria-label="Graph detail"><button data-detail="overview" class="${!universeDetail?'active':''}" aria-pressed="${!universeDetail}">Security domains <span>08</span></button><button data-detail="services" class="${universeDetail?'active':''}" aria-pressed="${universeDetail}">Attack surface <span>${services.length}</span></button></div><nav class="domain-dock" aria-label="Quick domain navigation">${domains.map(v=>`<a href="#/domain/${v.id}" style="--color:${v.color}">${icon(v.icon)}${esc(v.short)}</a>`).join('')}</nav>`);
    page.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{universeDetail=b.dataset.detail==='services';page.querySelectorAll('[data-detail]').forEach(el=>{const active=el===b;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});renderGraph();});
    const intro=document.createElement('div');intro.className='home-intro';intro.append(page.querySelector('.map-header'),page.querySelector('.inspector'));page.prepend(intro);
    const controls=document.createElement('div');controls.className='home-controls';controls.append(page.querySelector('.depth-bar'),page.querySelector('.map-bottom'));page.append(controls);
  }else{
    const thisRoute=location.hash||'#/',label=topic?.title||s?.name||d?.name;
    if(visits[0]?.url!==thisRoute){visits.unshift({url:thisRoute,label});visits.splice(7);}
    page.insertAdjacentHTML('beforeend',`<div class="reading-controls">${s?`<button class="bookmark-button ${saved.includes(s.id)?'saved':''}" aria-pressed="${saved.includes(s.id)}" id="save-service">${saved.includes(s.id)?'✓ Saved':'＋ Save service'}</button>`:''}<button id="focus-graph" aria-pressed="false">⤢ Focus graph</button></div>${visits.length>1?`<nav class="trail-history" aria-label="Recently explored"><span>TRAIL</span>${visits.slice(1,4).reverse().map(v=>`<a href="${esc(v.url)}">${esc(v.label)}</a>`).join('')}</nav>`:''}`);
    $('#focus-graph').onclick=()=>{const focused=page.classList.toggle('is-focus');$('#focus-graph').setAttribute('aria-pressed',String(focused));$('#focus-graph').textContent=focused?'↙ Show details':'⤢ Focus graph';$('#focus-graph').classList.toggle('focus-active',focused);};
    if(s)$('#save-service').onclick=()=>{const exists=saved.includes(s.id);saved=exists?saved.filter(id=>id!==s.id):[...saved,s.id];try{localStorage.setItem('trace-saved',JSON.stringify(saved));}catch{}$('#save-service').textContent=exists?'＋ Save service':'✓ Saved';$('#save-service').classList.toggle('saved',!exists);$('#save-service').setAttribute('aria-pressed',String(!exists));announce(exists?'Service removed from saved list':'Service saved. Find it with the Saved filter in the service library.');};
  }
}

