function scenarioPage(id){
  const scenario=scenarioById(id);if(!scenario)return notFound();
  routeState={type:'scenario',scenario};
  const sources=scenarioSources(scenario),rules=detectionCoverage(scenario.services),covered=new Set(rules.flatMap(rule=>rule.services)),gaps=scenario.services.filter(serviceId=>!covered.has(serviceId));
  $('#view').innerHTML=`<section class="content-page scenario-page">${breadcrumb([['Attack paths','#/paths'],[scenario.title]])}<article><header class="scenario-header"><div><span class="eyebrow">${esc(scenario.kicker)}</span><h1>${esc(scenario.title)}</h1><p>${esc(scenario.summary)}</p><div class="mitre-row">${scenario.mitre.map(v=>`<span>MITRE ${v}</span>`).join('')}</div></div><div class="scenario-confidence"><span>SCENARIO BASIS</span><strong>${esc(scenario.confidence)}</strong><small>Authorized testing and incident-response model</small></div></header><section class="attack-trace"><div class="section-heading"><span>01</span><div><small>ATTACK TRACE</small><h2>Follow the identity and control plane.</h2></div></div><div class="trace-stages">${scenario.stages.map((stage,i)=>{const service=serviceById(stage.service),domain=domainFor(stage.service);return `<div class="trace-stage" style="--color:${domain.color}"><a class="stage-service" href="#/service/${stage.service}">${icon(domain.icon)}<span><small>STAGE ${String(i+1).padStart(2,'0')} / ${esc(domain.short.toUpperCase())}</small><strong>${esc(service.name)}</strong></span></a><h3>${esc(stage.title)}</h3><p>${esc(stage.detail)}</p><div class="stage-signal"><span>OBSERVABLE</span><p>${esc(stage.signal)}</p></div></div>`;}).join('')}</div></section><div class="response-grid"><section><div class="section-heading"><span>02</span><div><small>DETECT</small><h2>Prove the sequence.</h2></div></div><ul>${scenario.detect.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></section><section><div class="section-heading"><span>03</span><div><small>CONTAIN</small><h2>Stop reach and preserve evidence.</h2></div></div><ul>${scenario.contain.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></section><section><div class="section-heading"><span>04</span><div><small>HARDEN</small><h2>Close the path.</h2></div></div><ul>${scenario.harden.map(v=>`<li>${esc(v)}</li>`).join('')}</ul></section></div><section class="scenario-detections"><div class="section-heading"><span>05</span><div><small>COMMUNITY COVERAGE</small><h2>Rules that touch this path.</h2></div></div><p>These are related service-level detections, not proof that the complete scenario occurred. Use their native logic as individual signals and correlate the path with the evidence above.</p><div class="scenario-detection-grid">${rules.map(rule=>`<a href="${esc(rule.source)}" target="_blank" rel="noopener noreferrer"><span>${esc(rule.language)} · ${esc(rule.contributor)}</span><strong>${esc(rule.title)}</strong><small>${esc(rule.signals[0])}</small></a>`).join('')||'<p class="empty-note">No reviewed community rule maps to this path yet.</p>'}</div>${gaps.length?`<div class="scenario-coverage-gap"><span>VISIBLE GAPS</span><p>${gaps.map(serviceId=>esc(serviceById(serviceId).name)).join(' · ')}</p></div>`:''}</section><section class="scenario-sources"><div class="section-heading"><span>06</span><div><small>PROVENANCE</small><h2>Research behind the path.</h2></div></div><p>Attack steps are paraphrased from the cited labs and research; response actions are synthesized from AWS guidance and incident playbooks. Prerequisite permissions and evidence limits remain explicit. No private target data or exploit payloads are published.</p><div>${sources.map(v=>`<a href="${esc(v.url)}" target="_blank" rel="noopener noreferrer"><span>${esc(v.kind)}</span><strong>${esc(v.publisher)}</strong><small>${esc(v.label)}</small></a>`).join('')}</div></section></article></section>`;
  const story=document.createElement('div');story.className='mind-story-host';$('.scenario-header').after(story);mountStory(story,scenario);
  enhanceScenarioReader($('.scenario-page'));
  document.title=`${scenario.title} - TRACE`;
}

function library(){routeState={type:'library'};let filter='all';$('#view').innerHTML=`<section class="content-page">${breadcrumb([['Service library']])}<div class="content-hero"><div><span class="eyebrow">THE INDEX / ${services.length} SECURITY NODES</span><h1>Find the next<br>control boundary.</h1><p>Search service context, exact rule signals, MITRE mappings, evidence requirements, tuning notes, attack paths, and official AWS documentation.</p></div></div><div class="library-tools"><input id="library-search" type="search" aria-label="Search service library" placeholder="Search services, events, MITRE IDs…">${[{id:'all',short:'All services'},{id:'saved',short:'Saved'},...domains].map(d=>`<button class="filter-button ${d.id==='all'?'active':''}" data-filter="${d.id}">${esc(d.short)}</button>`).join('')}</div><div class="library-results" id="library-count"></div><div class="library-grid" id="library-grid"></div></section>`;
 const fill=()=>{const q=$('#library-search').value.toLowerCase();const items=services.filter(s=>(filter==='all'||(filter==='saved'?saved.includes(s.id):domainFor(s.id).id===filter))&&`${s.name} ${s.label} ${profileFor(s.id).boundary} ${profileFor(s.id).threats.join(' ')} ${detectionSearchText(s.id)}`.toLowerCase().includes(q));$('#library-count').textContent=`${items.length} SERVICES`;$('#library-grid').innerHTML=items.map(s=>{const d=domainFor(s.id),ruleCount=detectionsForService(s.id).length;return `<a class="library-card" style="--color:${d.color}" href="#/service/${s.id}"><span class="card-arrow">↗</span>${icon(d.icon)}<span class="eyebrow">${esc(d.name.toUpperCase())}</span><h2>${esc(s.name)}</h2><p>${esc(profileFor(s.id).boundary)}</p><div class="card-source">${scenariosForService(s.id).length} attack paths / ${ruleCount} reviewed detection${ruleCount===1?'':'s'} / ${docFor(s.id)?.sections.length||0} AWS topics</div></a>`;}).join('')||'<p class="empty-note">No services match. Try a broader search or another domain.</p>';};fill();$('#library-search').oninput=fill;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));fill();});
}
function sources(){
  routeState={type:'sources'};const research=Object.values(researchSources),covered=services.filter(s=>detectionsForService(s.id).length),gaps=services.filter(s=>!detectionsForService(s.id).length);
  $('#view').innerHTML=`<section class="content-page sources-page">${breadcrumb([['Sources & methodology']])}<div class="content-hero"><div><span class="eyebrow">TRACEABLE BY DESIGN</span><h1>Every claim has<br>a way back.</h1><p>AWS documentation defines service behavior. Community detections remain in their native language with contributor, telemetry, tuning, and rule-level provenance attached.</p></div></div><div class="source-principles"><div><span>01</span><strong>Official behavior</strong><p>AWS service guides define features, controls, events, and limitations.</p></div><div><span>02</span><strong>Native detection logic</strong><p>TRACE distinguishes reviewed upstream selections from publisher-only summaries and never fabricates a common query dialect.</p></div><div><span>03</span><strong>Evidence before verdict</strong><p>A rule match is a lead. Telemetry prerequisites, false positives, scenario limits, and visible coverage gaps travel with it.</p></div></div><section class="reference-catalog"><div class="section-heading"><span>01</span><div><small>RESEARCH INDEX</small><h2>Tools, labs, references, and playbooks.</h2></div></div><div class="reference-grid">${research.map(v=>`<a href="${esc(v.url)}" target="_blank" rel="noopener noreferrer"><span>${esc(v.kind)}</span><h3>${esc(v.publisher)}</h3><p>${esc(v.label)}</p><small>Open source ↗</small></a>`).join('')}</div></section><section class="community-source-index"><div class="section-heading"><span>02</span><div><small>COMMUNITY DETECTION INDEX</small><h2>${communityDetections.length} reviewed rules. Original language intact.</h2></div></div><div class="sources-note">${communityDetections.length} community rules mapped to ${covered.length} of ${services.length} service nodes · reviewed ${esc(detectionReviewDate)}.<br>Unmapped nodes remain explicit: ${gaps.map(s=>esc(s.name)).join(' · ')}.</div><div class="community-source-grid">${communityDetections.map(rule=>`<a href="${esc(rule.source)}" target="_blank" rel="noopener noreferrer"><span>${esc(rule.language)} · ${esc(rule.contributor)}</span><h3>${esc(rule.title)}</h3><p>${esc(rule.summary)}</p><small>${esc(rule.basis)}${rule.mitre.length?' · '+rule.mitre.map(id=>'MITRE '+id).join(' · '):''} ↗</small></a>`).join('')}</div><div class="community-index-actions">${linkOut(detectionLibraryUrl,'Browse AWS detections on detections.ai','source-button')}</div></section><section class="aws-source-index"><div class="section-heading"><span>03</span><div><small>AWS SERVICE INDEX</small><h2>Imported documentation provenance.</h2></div></div><div class="sources-note">${docs.stats.fetched} of ${services.length} selected service pages imported / ${docs.stats.sections} headings / ${docs.stats.references} cross-service references.<br>Attack-path lines are analyst synthesis and are labeled separately from documented AWS relationships. Domains are editorial security groupings, not live account inventory.</div><div class="source-table-wrap"><table class="source-table"><thead><tr><th>SERVICE</th><th>DOMAIN</th><th>RULES</th><th>LAST FETCHED</th><th>OFFICIAL SOURCE</th></tr></thead><tbody>${services.map(s=>{const d=docFor(s.id);return `<tr><td><a href="#/service/${s.id}">${esc(s.name)}</a></td><td><span class="source-kind">${esc(domainFor(s.id).short.toUpperCase())}</span></td><td>${detectionsForService(s.id).length}</td><td>${date(d?.fetchedAt)}</td><td>${linkOut(profileFor(s.id).source,'Security guide')}</td></tr>`;}).join('')}</tbody></table></div><div class="sources-note methodology-note">The documentation importer publishes titles, anchors, headings, short attributed excerpts, retrieval dates, and hashes; it does not mirror articles. Detection cards preserve rule provenance and summarize only what was publicly reviewable. Field mappings and thresholds must be validated in the destination platform. <a href="./generated/docs.json">Download the documentation index ↗</a></div></section></section>`;
  document.title='Sources and methodology - TRACE';
}
function concept(id){const article=insights.find(x=>x.id===id);if(!article)return notFound();routeState={type:'concept'};$('#view').innerHTML=`<section class="content-page">${breadcrumb([['Concepts'],[article.title]])}<article class="article"><span class="eyebrow">${esc(article.tag)} · SOURCE-BASED EXPLANATION</span><h1>${esc(article.title)}</h1><p>${esc(article.description)}</p><div class="article-flow">${article.services.map((id,i)=>`${i?'<span>↔</span>':''}<a href="#/service/${id}" style="--color:${domainFor(id).color}">${esc(serviceById(id).name)}</a>`).join('')}</div><p>${esc(article.body)}</p><div class="sources-note">The diagram groups the services discussed in this concept; the source links below explain their relationship.</div>${[article.source,...article.sources||[]].map(url=>linkOut(url,'Read the supporting AWS documentation','source-button')).join('')}</article></section>`;}
function notFound(){routeState={type:'404'};$('#view').innerHTML='<section class="content-page"><h1>This node isn’t in the atlas.</h1><p><a class="text-link" href="#/">Return to the universe →</a></p></section>';}
function route(){cleanupMindPage();cleanupResearchHome();cleanupMindPage=()=>{};cleanupResearchHome=()=>{};graphPage=0;const [type,id,sub,index]=location.hash.replace(/^#\/?/,'').split('/');activeTab='intel';graphMode='security';if(type==='library')library();else if(type==='paths')attackPaths();else if(type==='scenario')scenarioPage(id);else if(type==='sources')sources();else if(type==='concept')concept(id);else if(type==='domain')mapPage('domain',id);else if(type==='service')mapPage('service',id,sub==='topic'?Number(index):undefined);else if(!type)cleanupResearchHome=mountResearchHome($('#view'),{topicCount:docs.stats.sections,openSearch});else notFound();document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(type==='library'?'library':type==='paths'||type==='scenario'?'paths':type==='sources'?'sources':'map')));document.querySelectorAll('[data-domain]').forEach(a=>a.classList.toggle('active',a.dataset.domain===(type==='domain'?id:domainFor(id)?.id)));window.scrollTo(0,0);announce(document.querySelector('h1')?.textContent||'Atlas updated');}
function openSearch(){const dialog=$('#search-dialog');if(!dialog.open)dialog.showModal();$('#search-input').value='';searchResults('');$('#search-input').focus();}
function searchResults(query){const q=query.toLowerCase().trim();let results=[...services.filter(s=>`${s.name} ${s.label} ${profileFor(s.id).boundary} ${profileFor(s.id).threats.join(' ')} ${detectionSearchText(s.id)}`.toLowerCase().includes(q)).map(s=>({label:s.name,sub:s.label,url:`#/service/${s.id}`,d:domainFor(s.id)})),...domains.filter(d=>d.name.toLowerCase().includes(q)).map(d=>({label:d.name,sub:'Architecture domain',url:`#/domain/${d.id}`,d}))];if(q.length>=2){communityDetections.filter(rule=>`${rule.title} ${rule.summary} ${rule.language} ${rule.contributor} ${rule.signals.join(' ')} ${rule.mitre.join(' ')}`.toLowerCase().includes(q)).forEach(rule=>{const serviceId=rule.services[0];results.push({label:rule.title,sub:`${rule.language} detection · ${serviceById(serviceId).name}`,url:`#/service/${serviceId}`,d:domainFor(serviceId)});});docs.documents.filter(d=>d.status==='ok').forEach(doc=>doc.sections.forEach((t,i)=>{if(t.title.toLowerCase().includes(q))results.push({label:t.title,sub:serviceById(doc.id).name+' · Source topic',url:`#/service/${doc.id}/topic/${i}`,d:domainFor(doc.id)});}));}$('#search-results').innerHTML=results.slice(0,30).map(r=>`<a class="search-result" style="--color:${r.d.color}" href="${r.url}">${icon(r.d.icon)}<span>${esc(r.label)}<small>${esc(r.sub)}</small></span><span class="result-arrow">↗</span></a>`).join('')||'<p class="empty-note" style="padding:15px">No matching nodes. Try a service name, event, MITRE ID, rule title, or AWS topic.</p>';$('#search-results').querySelectorAll('a').forEach(a=>a.onclick=()=>$('#search-dialog').close());}
$('.search-launch').onclick=openSearch;$('#search-input').oninput=e=>searchResults(e.target.value);$('#search-close').onclick=()=>$('#search-dialog').close();$('#search-dialog').onclick=e=>{if(e.target===$('#search-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}};
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}});window.addEventListener('hashchange',route);route();
$('#search-dialog').addEventListener('keydown',e=>{const results=[...$('#search-results').querySelectorAll('a')];if(!results.length)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const index=results.indexOf(document.activeElement);const next=index<0?(e.key==='ArrowDown'?0:results.length-1):(index+(e.key==='ArrowDown'?1:results.length-1))%results.length;results[next].focus();}else if(e.key==='Enter'&&e.target===$('#search-input')){e.preventDefault();results[0].click();}});
matchMedia('(max-width:650px)').addEventListener('change',()=>{if($('.world-svg')&&!$('.research-home'))renderGraph();});
